sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Get the current reservation status as a plain string
    var status = current.reservation_status.toString();

    // Query the Reservation Tracker table to update the OOB state field
    // We use a GlideRecord instead of setting current directly because
    // this is an after rule — current is already saved, so we update separately
    var gr = new GlideRecord('x_746154_workspa_0_reservation_tracker');
    if (!gr.get(current.sys_id)) return;

    // Checked-in means the reservation is actively in progress → state: Open (1)
    if (status == 'checked_in') {
        gr.state = 1; // Open

    // No-show or Cancelled means it was skipped or voided → state: Closed Skipped (4)
    } else if (status == 'no_show' || status == 'cancelled') {
        gr.state = 7; // Closed Skipped

    // Checked-out means the reservation completed successfully → state: Closed Complete (3)
    } else if (status == 'checked_out') {
        gr.state = 3; // Closed Complete
    }

    // Save the updated state back to the record
    gr.update();

})(current, previous);
